def apply_russian_builds(pages):
    SOURCES['rub130'] = ('https://wow.aethus.pl/', 'Aethus · оригинальный клиент',
        'Английский текст оригинала v0.130.0 / e7d9dd47, снимок от 30.10.2026; условия девяти классов перечитаны 05.11.2026. Это датированные объяснения механик, не повторный тест последней версии. Значения с незаполненными шаблонами не подставлены.')
    SOURCES['rub139'] = ('https://wow.aethus.pl/', 'Aethus · проверка талантов',
        'Примеры Mage/Warlock используют проверенные 03.11.2026 деревья оригинала v0.139.2 / 5cb6deb36: пределы рангов, пороги рядов и зависимости. Каждый пример содержит 31 очко и оставляет 20 свободными. Проверка меню и правил, без прохождения или сравнительного теста урона. Изменения Enhancement сверены отдельно по строкам v0.139.0 от 02.11.2026.')
    SOURCES['rubsave'] = ('https://wow.aethus.pl/saves.js', 'Aethus · экспорт и импорт сохранений',
        'Мост сохранений прочитан 29.10.2026. Экспорт файла и передача текста импорта клиенту; файл проверяет сама игра. Совместимость всех версий и изменённых сохранений не проверена.')
    for page in pages:
        if page['slug'] != 'ru/builds/':
            continue
        # Preserve this existing page's title, description, H1, URL and old anchors.
        page['answer'] = 'Выберите класс и механизм урона, затем сравните доступные таланты, карты заклинаний и экипировку. Ниже — девять классов, порядок решений по этапам и два примера на 31 очко для мага и чернокнижника. Ссылки на подробные английские маршруты отмечены EN. '+ref('rub130')+ref('rub139')
        page['review_note'] = 'Обновлено 5 ноября 2026 · Девять классов · Механики v0.130.0 и отдельные проверки v0.139.x указаны в источниках · Без нового игрового теста'
        rows = [[name, branch, '<a href="#'+slug+'">'+core+'</a>'] for slug, name, branch, core, _, _ in ROUTES]
        profiles = ''
        for slug, name, branch, core, priority, limit in ROUTES:
            profiles += '<section id="'+slug+'"><h3>'+name+' · '+branch+'</h3>'+para(priority)+para(limit)+para(a('builds/'+slug+'/', 'Подробный маршрут '+name+' (EN)'))+'</section>'
        mage = example_table('mage-fire').replace('Points in this sequence', 'Очки по порядку').replace('Talent', 'Талант (EN)').replace('Rank reached', 'Достигнутый ранг')
        warlock = example_table('warlock-affliction').replace('Points in this sequence', 'Очки по порядку').replace('Talent', 'Талант (EN)').replace('Rank reached', 'Достигнутый ранг')
        page['parts'] = [
            ('routes', 'Билды всех девяти классов', table(['Класс', 'Ветки для сравнения', 'Заклинания и маршрут'], rows)+para('Билд включает выбранные таланты, заклинания, карты улучшений и предметы. Одна таблица классов не определяет порядок всех 51 очка. Выбирайте доступный этап, а не только финальный талант. '+ref('rub130'))),
            ('order', 'Что выбирать на каждом этапе', table(['Этап героя', 'Приоритет', 'Что проверить'], [
                ['Новый герой', 'Рабочее стартовое заклинание, место для движения и нужное восстановление.', 'Не рассчитывайте на призыв, форму или смену старта от ещё не открытого таланта.'],
                ['Первые таланты', 'Один механизм и его зависимости.', 'Порог ряда требует очков в этой ветке; сам узел покупается дополнительным очком.'],
                ['Сборка уже работает', 'Урон или покрытие основного заклинания, затем нужная защита.', 'Для критического срабатывания нужен критический удар, для цепочки смертей — погибшие цели.'],
                ['Финальный талант открыт', 'Карты для нового стартового заклинания и реальных взаимодействий.', 'Пересмотрите прежние приоритеты после смены старта.'],
                ['Босс остановил забег', 'Попадание по одному живому боссу и причина смерти.', 'Бонусы за прыжки и убийства могут терять часть пользы без дополнительных врагов.']])+para(ref('rub130')+ref('rub139'))),
            ('class-routes', 'Приоритеты и ограничения по классам', para('Это рекомендации по механизму сборки, основанные на датированном тексте оригинала. Они не задают измеренный рейтинг урона. '+ref('rub130')+ref('rub139'))+profiles),
            ('examples', 'Два примера талантов на 31 очко', para('Примеры используют существующий проверенный справочник нашего планировщика для v0.139.2. Они проходят проверку лимитов и зависимостей и оставляют 20 очков нераспределёнными. Используйте только заработанный бюджет; оставшиеся очки выбирайте после оценки урона и выживания. '+ref('rub139'))+'<h3 id="mage-example">Маг Fire</h3>'+mage+para('До смены старта поддерживайте Fireball. После Pyroclasm усиливайте доступный Pyroblast и огненные взаимодействия. Если проблема в выживании, сравните предложенную защиту с очередным бонусом покрытия. Карты и конкретный амулет не гарантированы.')+para(a('build-planner/#example=mage-fire', 'Открыть пример Fire в планировщике (EN)'))+'<h3 id="warlock-example">Чернокнижник Affliction</h3>'+warlock+para('Получите Corruption или Curse of Agony из реальных предложений. Seed of Corruption меняет старт на Corruption. Contagion требует смерти цели; для одиночного босса отдельно сравните постоянный урон и восстановление.')+para(a('build-planner/#example=warlock-affliction', 'Открыть пример Affliction в планировщике (EN)'))),
            ('gear', 'Экипировка: что усиливать сначала', para('Разделяйте постоянную классовую экипировку Armory и украшения, получаемые в забеге. Сначала определите недостающую функцию. Следующие примеры — выбор по описанию эффекта в v0.130.0, без обещания лучшего комплекта или выпадения. '+ref('rub130'))+table(['Проблема или цель', 'Что сравнить', 'Ограничение'], [
                ['Медленно возвращается основное заклинание', 'Восстановление перезарядки, например Hand of Justice.', 'Проверяйте, какое заклинание действительно делает работу.'],
                ['Нужны критические срабатывания', 'Шанс крита, например Master Dragonslayer’s Ring.', 'Урон крита Blackhand’s Breadth не добавляет сам шанс.'],
                ['Толпа занимает всю область', 'Площадь действия, например Ring of Spell Power.', 'Площадь не доказывает рост урона по одиночному боссу.'],
                ['Не хватает постепенного восстановления', 'Лечение от нанесённого урона, например Blooddrinker’s Band.', 'Если вы не наносите урон, такой эффект не заменяет защиту.'],
                ['Быстрые удары убивают до лечения', 'Запас здоровья, щит и позиционирование; сравните Heavy Dark Iron Ring.', 'Высокий урон не исправляет каждую причину смерти.']])+para(a('armory/', 'Постоянная экипировка и источники (EN)')+' · '+a('items/', 'Кольца, аксессуары и амулеты (EN)'))),
            ('terms', 'Русские объяснения и английские названия', table(['Термин', 'Что он означает здесь'], [['Билд / сборка', 'Совместный план талантов, заклинаний, улучшений и предметов.'], ['Талант / talent', 'Постоянный выбор очков между забегами.'], ['Карта улучшения / upgrade', 'Предложение во время забега, которое поддерживает уже выбранный механизм.'], ['Финальный талант / capstone', 'Узел, который может менять старт или основное взаимодействие.'], ['Периодический урон / DoT', 'Эффект с повторными тиками. Урон тика и условие срабатывания таланта проверяются отдельно.'], ['Armory / Codex', 'Классовая экипировка и справочник предметов — разные проверки перед выбором.']])+para('Английские имена оставлены для поиска в клиенте и планировщике. Русский текст поясняет выбор, но не объявляет каждое название официальным переводом. Последняя обнаруженная версия игры показана отдельно от даты проверки конкретной сборки.')),
            ('save', 'Сохраните прогресс перед сменой клиента', para('Откройте Options → Saves → Export Save там, где существует прогресс. Перед Import Save экспортируйте и целевую сторону: импорт заменяет её прогресс. Ссылка на таланты планировщика содержит план, а не игровой сейв. '+ref('rubsave'))+para(a('ru/play/', 'Открыть оригинал и прочитать помощь на русском')+' · '+a('save-backup/', 'Экспорт, импорт и резервные копии (EN)'))),
            ('faq', 'Вопросы о сборках', '<h3>Какой билд самый сильный?</h3>'+para('Зависит от заработанных талантов, экипировки, зоны и сложности. Сначала выберите работающий маршрут выше. '+a('tier-list/', 'Датированный рейтинг классов (EN)')+' помогает сравнить другую задачу — классы, а не каждую раскладку очков.')+'<h3>Можно ли сразу скопировать 51 очко?</h3>'+para('На этой странице даны два проверяемых ядра по 31 очку. Если у героя меньше очков, финальный эффект ещё недоступен. Полную раскладку проверяйте по текущим порогам и зависимостям, а не дополняйте случайными рангами.')+'<h3>Где планировать и делиться билдом?</h3>'+para(a('build-planner/', 'Наш планировщик Mage и Warlock (EN)')+' поддерживает эти два класса. '+a('asbuilder/', 'Обзор ASBuilder (EN)')+' объясняет отдельный онлайн-инструмент и коды ASB2. Коды разных планировщиков не объявлены взаимозаменяемыми.'))
        ]
        page['related'] = [('ru/play/', 'Играть: помощь на русском'), ('builds/', 'Все подробные маршруты (EN)'), ('damage-meter/', 'Сравнить попытки по урону (EN)')]
    return pages


def decorate_russian_builds(html):
    html = localize_shell(html, 'ru')
    html = html.replace('href="'+P+'ru/play/" class="nav-play" aria-current="page"', 'href="'+P+'ru/play/" class="nav-play"')
    html = html.replace('href="'+P+'builds/">Билды (EN)</a>', 'href="'+P+'ru/builds/" aria-current="page">Билды</a>')
    return html.replace('Original game · Independent guide', 'Оригинальная игра · Независимый гайд').replace('Megabonk.org editors ·', 'Редакция Megabonk.org ·').replace('On this page', 'На этой странице').replace('Scrollable comparison', 'Таблица с горизонтальной прокруткой')
